// Titles and units follow the work actually executed by this spacecraft.
export function workspaceFor(id,h){
 const base=cfg[id],q=h?.ai;if(!base||!q)return base;
 const unit=q.unit,rate=unit+'/s';
 if(id==='purpose'||id==='conops'){
  const expanded=rows=>rows.map(r=>r.replace('work units/s',rate).replace('work units',unit));
  return {...base,charts:expanded(base.charts),metrics:expanded(base.metrics),rows:expanded(base.rows)};
 }
 if(q.purposeId==='text')return base;
 if(id==='compute')return {charts:['aiUnitRate|Onboard work rate|'+rate,'aiHostKW|Host demand|kW','aiFabricKW|Fabric demand|kW','itKW|IT demand|kW'],metrics:['aiUnitRate|Onboard processing|'+rate,'aiUnitsComputed|Cumulative work|'+unit,'aiInputBufferGB|Staged input|GB','itKW|IT demand|kW'],rows:['$trays|Installed compute trays|','aiUnitsComputed|Computed since launch|'+unit,'aiInputConsumedGB|Input processed|GB','aiProductGeneratedGB|Customer product generated|GB','aiHostKW|Host demand|kW','aiFabricKW|Fabric demand|kW']};
 if(id==='data')return {charts:['aiInputBufferGB|Staged input|GB','aiProductQueueGB|Customer product backlog|GB','aiProductGeneratedGB|Cumulative product generated|GB','aiProductDeliveredGB|Product received on Earth|GB'],metrics:['aiInputConsumedGB|Input consumed|GB','aiProductQueueGB|Awaiting delivery|GB','aiProductDeliveredGB|Earth receipt|GB','freeTB|Free recorder capacity|TB'],rows:['aiInputUploadedGB|Input received onboard|GB','aiInputBufferGB|Input available|GB','aiProductGeneratedGB|Generated product|GB','aiProductDeliveredGB|Returned product|GB','aiProductQueueGB|Queued product|GB','droppedGB|All traffic dropped|GB']};
 return base;
}
